<section class="invoice-review-step" id="invoice-review-payment" data-review-step="payment"><h3><?=e($invoiceEntryText('Bereits bezahlt?'))?></h3><div class="form-grid"><label><?=e($invoiceEntryText('Bezahlt von'))?><select class="form-control" name="payment_source" data-reimbursement-source><option value="none" <?= input($guided,'payment_source','none')==='none'?'selected':'' ?>><?=e($invoiceEntryText('Noch nicht bezahlt'))?></option><option value="club" <?= input($guided,'payment_source')==='club'?'selected':'' ?>><?=e($invoiceEntryText('Verein'))?></option><option value="private_advance" <?= input($guided,'payment_source')==='private_advance'?'selected':'' ?>><?=e($invoiceEntryText('Mitglied privat'))?></option></select></label></div><noscript><p><button name="invoice_read" value="refresh" formnovalidate class="btn btn-outline theme-secondary"><?=e($invoiceEntryText('Auswahl anzeigen'))?></button></p><p><?=e($invoiceEntryText('Nach einer geänderten Auswahl die zugehörigen Felder anzeigen. Es wird noch nichts gespeichert.'))?></p></noscript><div data-reimbursement-panel <?= input($guided,'payment_source','none')==='private_advance'?'':'hidden' ?>><div class="form-grid"><label><?=e($invoiceEntryText('Erstattung an Mitglied'))?><select class="form-control" name="reimbursement_contact" data-reimbursement-contact><option value=""><?=e($invoiceEntryText('Bitte auswählen'))?></option><?php if($guided['reimbursement_contact']!==''&&!in_array($guided['reimbursement_contact'],array_column($reimbursementMembers,'id'),true)):?><option value="<?=e($guided['reimbursement_contact'])?>" selected><?=e($invoiceEntryText('Ursprüngliche Auswahl derzeit nicht verfügbar'))?></option><?php endif?><?php foreach($reimbursementMembers as $member): ?><option value="<?= e($member['id']) ?>" <?= input($guided,'reimbursement_contact')===$member['id']?'selected':'' ?>><?= e($member['name']) ?></option><?php endforeach ?></select></label><label><?=e($invoiceEntryText('Rechnung steht auf'))?><select class="form-control" name="invoice_recipient" data-invoice-recipient><option value="club" <?= input($guided,'invoice_recipient','club')==='club'?'selected':'' ?>><?=e($invoiceEntryText('Verein'))?></option><option value="member" <?= input($guided,'invoice_recipient')==='member'?'selected':'' ?>><?=e($invoiceEntryText('Mitglied'))?></option><option value="other" <?= input($guided,'invoice_recipient')==='other'?'selected':'' ?>><?=e($invoiceEntryText('Andere Person'))?></option><option value="unknown" <?= input($guided,'invoice_recipient')==='unknown'?'selected':'' ?>><?=e($invoiceEntryText('Noch unklar'))?></option></select></label></div><p class="muted" data-reimbursement-note></p></div></section>
